const snip = (file, from, to) => {
  const s = rd(file).split(/\r?\n/); const a = s.findIndex((l) => from.test(l)); const b = s.findIndex((l, i) => i >= a && to.test(l));
  return s.slice(a, b + 1).join('\n');
};

